// Inputs
let partCount = Number(msg.payload.partCount);
let cycleTimeMinutes = Number(msg.payload.idealCycleTime);
let totalProductionMinutes = partCount * cycleTimeMinutes;

let startStr = msg.payload.startDateTime;
let shiftStart = "01:10";
let shiftEnd = "23:59";

// Parse start datetime
//let [day, month, yearTime] = startStr.split("/");
//let [year, time] = yearTime.split(" ");
// Check that startStr exists
if (typeof startStr !== 'string')  
 {
    node.error("startStr is missing or not a string", msg);
    return null;
}

// Try parsing the date safely
let dateParts = startStr.split("/");
if (dateParts.length !== 3)
 {
    node.error("startStr format should be DD/MM/YYYY HH:mm", msg);
    return null;
}

let [day, month, yearTime] = dateParts;
let yearTimeParts = yearTime.split(" ");
if (yearTimeParts.length !== 2) 
{
    node.error("startStr time part is missing (expected 'YYYY HH:mm')", msg);
    return null;
}

let [year, time] = yearTimeParts;

// Pad values to ensure proper format (e.g. 09 not 9)
let isoStartStr = `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}T${time}:00`;
let currentDate = new Date(isoStartStr);

// Handle invalid date
if (isNaN(currentDate.getTime())) 
{
    node.error("Invalid date constructed from startStr", msg);
    return null;
}



// Shift start and end as minutes from midnight
let [shiftStartHour, shiftStartMin] = shiftStart.split(":").map(Number);
let [shiftEndHour, shiftEndMin] = shiftEnd.split(":").map(Number);
let shiftStartMinutes = shiftStartHour * 60 + shiftStartMin;
let shiftEndMinutes = shiftEndHour * 60 + shiftEndMin;
let dailyShiftMinutes = shiftEndMinutes - shiftStartMinutes;

if (dailyShiftMinutes <= 0) 
{
    node.error("Invalid shift time range", msg);
    return null;
}

let minutesLeft = totalProductionMinutes;
let endDate;

// Loop day by day, allocating production time
while (minutesLeft > 0) {
    // Get the date string (YYYY-MM-DD)
    let dateStr = currentDate.toISOString().split("T")[0];

    // Calculate start and end time for this day's shift
    let shiftStartDateTime = new Date(`${dateStr}T${shiftStart}:00`);
    let shiftEndDateTime = new Date(`${dateStr}T${shiftEnd}:00`);

    // If current time is before shift start, move to shift start
    if (currentDate < shiftStartDateTime) {
        currentDate = new Date(shiftStartDateTime);
    }

    // If current time is after shift end, move to next day at shift start
    if (currentDate >= shiftEndDateTime) {
        currentDate.setDate(currentDate.getDate() + 1);
        currentDate.setHours(shiftStartHour, shiftStartMin, 0, 0);
        continue;
    }

    // Calculate available minutes today from current time
    let availableToday = (shiftEndDateTime - currentDate) / 60000;
    let usedToday = Math.min(availableToday, minutesLeft);

    // Move time forward by used minutes
    currentDate = new Date(currentDate.getTime() + usedToday * 60000);
    minutesLeft -= usedToday;

    // If finished, save as endDate
    if (minutesLeft <= 0) {
        endDate = currentDate;
    } else {
        // Move to next day's shift
        currentDate.setDate(currentDate.getDate() + 1);
        currentDate.setHours(shiftStartHour, shiftStartMin, 0, 0);
    }
}

